import fs from 'node:fs/promises';import assert from 'node:assert/strict';
const root='/Users/zhengwei/Downloads/clock-design-20261007';
const read=async n=>JSON.parse(await fs.readFile(root+'/'+n,'utf8'));
const api=async(p,b)=>{const r=await fetch('http://127.0.0.1:3000/api/footage/templates'+p,{method:b?'POST':'GET',headers:{'content-type':'application/json','x-requested-with':'moirai-footage'},body:b?JSON.stringify(b):undefined});const d=await r.json();assert.ok(r.ok,JSON.stringify(d));return d;};
const application=await read('application.json'),item=await read('item-0.json'),batch=await read('batch.json');
assert.equal(batch.renderJob.status,'succeeded');assert.equal(item.status,'published');
assert.equal((await api('/dynamic-assets/'+application.assetId)).definition.revision,application.assetRevision);
const review={templateId:item.templateId,templateRevision:item.templateRevision,batchId:batch.id,item:0,reviewer:'Codex · clock design visual review · 2026-10-07',composition:{score:23,rationale:'1280×720 exact Application: Alex full hold and same-source r4/r5 comparison preserve the person and Sun diagram with clear upper-right separation. Two Chinese audio fixtures provide clean black-ground visibility. More backgrounds and placement variants were not part of this score.'},motion:{score:21,rationale:'Inspected 76 consecutive encoded 30fps event frames across three positive fixtures, including entry, hold, exit and adjacent outside frames. Case settle and hand turn are layered; no visible detached tips or post-event residue in these strips. Shortest 0.36s event leaves only about 0.18s stable hold, sufficient for a qualitative icon cue but not time reading; stronger rhythm/longer-event combinations remain unreviewed.'},assets:{score:18,rationale:'28 native editable graphic leaves add casing depth, narrow highlight, face bevel, twelve radial ticks, paired hand highlights and brass pivot. Material hierarchy and mark clarity improve visibly over same-source r4. The design remains a restrained flat-vector clock rather than a fully textured illustration; no external bitmap.'},adaptation:{score:15,rationale:'Three independent measured transcripts cover English month, Chinese duration and deadline semantics at 0.36/0.66/0.92s. One explicit no-time-keyword negative yields zero overlays. Saved style and exact Application are identical for all four fixtures. Coverage is one live-action positive and two audio black grounds at one landscape size; no portrait, tiny-scale or dense-event guarantee.'},editability:{score:9,rationale:'Workbench lists 28 leaf layers and root; nine representative layers were selected. Rim-highlight fill was actually changed, native preview updated, restored and reloaded with saved r5 intact. Native compiled hand geometry retains common pivot within 0.2422px on 541 entry samples per moving piece. Arbitrary hand length edits still require recomputing shared-pivot compensation.'},evidence:item.previews.map(p=>({fixture:p.fixture,sha256:p.sha256})),inspection:'Frame-based inspection only: 3 actual r5 full holds, same-source r4/r5 comparison, all 17+26+33=76 encoded event frames (fixtures 0:38–54, 1:100–125, 2:197–229), negative fixture at 6s plus compiled overlay absence, native black/white/checker hold renders, and UI layer edit/restore. Decoded 48kHz stereo s16le PCM matched r4 for all four fixtures. No continuous video playback viewing or listening performed.',limitations:'Internal candidate score applies only to saved clock r5 and this exact 1280×720/30fps scale0.4 center0.83,0.25 Application with the three positive inputs and explicit negative. Not a universal style score, not ≥90 qualification, not a new design family, not a real-time clock. Portrait, smaller sizes, shorter/dense events, additional bright/complex backgrounds, caption combinations, continuous-motion perception and listening remain unreviewed.',blockingFindings:[],listened:false};
const submission={application,review};await fs.writeFile(root+'/quality-review-request.json',JSON.stringify(submission,null,2));const receipt=await api('/dynamic-assets/reviews',submission);await fs.writeFile(root+'/quality-review-receipt.json',JSON.stringify(receipt,null,2));
const reread=await api('/dynamic-assets/reviews?assetId='+application.assetId);await fs.writeFile(root+'/quality-reviews-reread.json',JSON.stringify(reread,null,2));const row=reread.reviews.find(r=>r.id===receipt.id);assert.equal(receipt.total,86);assert.equal(receipt.meetsInternalThreshold,false);assert.ok(row.current&&row.evidenceCurrent);console.log(JSON.stringify({id:receipt.id,total:receipt.total,current:row.current,evidenceCurrent:row.evidenceCurrent,meetsInternalThreshold:receipt.meetsInternalThreshold}));
